package com.inovagab.inovagab.controller; import com.inovagab.inovagab.dto.*; import com.inovagab.inovagab.model.Projeto; import com.inovagab.inovagab.service.AuditoriaService; import com.inovagab.inovagab.service.ProjetoService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/projetos") public class ProjetoController {private final ProjetoService service; private final AuditoriaService auditoria; public ProjetoController(ProjetoService service,AuditoriaService auditoria){this.service=service;this.auditoria=auditoria;} @PostMapping public ResponseEntity<Projeto> criar(@Valid @RequestBody ProjetoRequest r,Authentication a){Projeto projeto=service.criar(r);auditoria.registrar(a.getName(),"CRIAR","PROJETO",projeto.getId(),projeto.getNome());return ResponseEntity.status(HttpStatus.CREATED).body(projeto);} @GetMapping public List<Projeto> listar(){return service.listar();} @PutMapping("/{id}") public Projeto atualizar(@PathVariable String id,@Valid @RequestBody ProjetoRequest r,Authentication a){Projeto projeto=service.atualizar(id,r);auditoria.registrar(a.getName(),"ATUALIZAR","PROJETO",id,projeto.getNome());return projeto;}@PatchMapping("/{id}/progresso") public Projeto progresso(@PathVariable String id,@Valid @RequestBody ProgressoRequest r,Authentication a){Projeto projeto=service.progresso(id,r);auditoria.registrar(a.getName(),"ATUALIZAR_PROGRESSO","PROJETO",id,"Progresso: "+projeto.getProgresso()+"%");return projeto;}@PatchMapping("/{id}/resultados") public Projeto resultados(@PathVariable String id,@Valid @RequestBody ResultadoRequest r,Authentication a){Projeto projeto=service.resultados(id,r);auditoria.registrar(a.getName(),"REGISTRAR_RESULTADO","PROJETO",id,projeto.getNome());return projeto;} }
